def cycpattern_check(a: str, b: str) -> bool:
    """Return True if any rotation of `b` appears as a substring of `a`."""
    if not b:
        return True  # empty string is a substring of any string

    if len(b) > len(a):
        return False

    # Generate all rotations of b
    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True
    return False

# Example usage
if __name__ == "__main__":
    tests = [
        ("abcd", "abd", False),
        ("hello", "ell", True),
        ("whassup", "psus", False),
        ("abab", "baa", True),
        ("efef", "eeff", False),
        ("himenss", "simen", True),
    ]
    for a, b, expected in tests:
        result = cycpattern_check(a, b)
        print(f"cycpattern_check({a!r}, {b!r}) => {result} (expected {expected})")
        assert result == expected, f"Test failed for {a!r}, {b!r}"
